begin read only;
set local statement_timeout = '5s';
select jsonb_build_object(
 'observed_at',clock_timestamp(),'transaction_read_only',current_setting('transaction_read_only'),
 'cleanup',(select jsonb_build_object('state',state,'mode',mode,'attempts',attempts,'entry_count',entry_count,
 'cleanup_deadline',cleanup_deadline,'completed_at',completed_at)
 from private.own_prepared_cleanups where id='a56c3ee5-f30d-4517-95dd-fad012004434'::uuid
 and job_id='073724a4-a81e-4bc9-83d5-7cff376691e8'::uuid),
 'remaining_job_rows',(select count(*) from private.own_preparation_jobs where id='073724a4-a81e-4bc9-83d5-7cff376691e8'::uuid),
 'remaining_artifact_rows',(select count(*) from private.own_preparation_artifacts where job_id='073724a4-a81e-4bc9-83d5-7cff376691e8'::uuid),
 'remaining_checkpoint_rows',(select count(*) from private.own_preparation_checkpoints where job_id='073724a4-a81e-4bc9-83d5-7cff376691e8'::uuid),
 'remaining_cleanup_entry_rows',(select count(*) from private.own_prepared_cleanup_entries where cleanup_id='a56c3ee5-f30d-4517-95dd-fad012004434'::uuid),
 'original_file',(select jsonb_build_object('status',status,'stored_bytes',size_bytes,
 'stored_sha256_matches_attempt',sha256='7b2a9238c3fd1124bd6d4e9cebdc7057112f056aa5864ef05b79f834f0a5922c',
 'has_completed_normalization',normalization_completed_at is not null)
 from public.genome_files where id='4f16c6f4-b809-43ac-9e37-f837da653750'::uuid)
) as observation;
rollback;
